package dev.aegis.review.application;

import static org.assertj.core.api.Assertions.*;
import dev.aegis.identity.application.api.*; import dev.aegis.notifications.application.api.*; import dev.aegis.review.application.ports.*; import dev.aegis.review.domain.*; import dev.aegis.shared.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;

class ReviewServiceTest {
 private static final MemberId LISA=MemberId.random(), CEDRIC=MemberId.random(); private static final Actor ACTOR=new Actor(LISA); private final MemoryRepository repo=new MemoryRepository(); private final MutableProducer producer=new MutableProducer(); private final List<NoticeDraft> notices=new ArrayList<>(); private final List<String> actions=new ArrayList<>();
 private final ReviewService service=new ReviewService(repo,List.of(producer),(actor,item,action)->actions.add(action+":"+item.id()),actor->{if(actor==null||!Set.of(LISA,CEDRIC).contains(actor.memberId()))throw new NotAuthorizedException("member required");},directory(),draft->{notices.add(draft);return PublishNotice.PublishOutcome.PUBLISHED;},Clock.fixed(Instant.parse("2026-09-21T10:00:00Z"),ZoneOffset.UTC));
 @Test void reconciliationDeduplicatesAndNotifiesBothMembersOnce(){producer.items=List.of(candidate(1));assertThat(service.list(ACTOR,"OPEN",null)).hasSize(1);assertThat(service.list(ACTOR,"OPEN",null)).hasSize(1);assertThat(notices).hasSize(2).extracting(NoticeDraft::linkType).containsOnly("REVIEW");}
 @Test void dismissalSurvivesAnUnchangedProducerAndNewEvidenceSupersedesIt(){producer.items=List.of(candidate(1));var item=service.list(ACTOR,"OPEN",null).getFirst();service.dismiss(ACTOR,item.id(),item.version());assertThat(service.list(ACTOR,"DISMISSED",null)).hasSize(1);producer.items=List.of(candidate(2));assertThat(service.list(ACTOR,"OPEN",null)).singleElement().satisfies(next->assertThat(next.sourceVersion()).isEqualTo(2));assertThat(service.list(ACTOR,"SUPERSEDED",null)).isEmpty();}
 @Test void actionIsVersionCheckedAndDelegated(){producer.items=List.of(candidate(1));var item=service.list(ACTOR,"OPEN",null).getFirst();service.act(ACTOR,item.id(),"RETRY",item.version());assertThat(actions).containsExactly("RETRY:"+item.id());assertThatThrownBy(()->service.dismiss(ACTOR,item.id(),item.version())).isInstanceOf(StaleVersionException.class);}
 @Test void outsidersCannotReadOrAct(){assertThatThrownBy(()->service.list(new Actor(MemberId.random()),null,null)).isInstanceOf(NotAuthorizedException.class);}
 @Test void exportAndIdempotentRestorePreserveLifecycleAndIdentity(){producer.items=List.of(candidate(1));var item=service.list(ACTOR,"OPEN",null).getFirst();service.dismiss(ACTOR,item.id(),item.version());var exported=service.exportAll(ACTOR);MemoryRepository restored=new MemoryRepository();ReviewService target=new ReviewService(restored,List.of(),(a,i,x)->{},a->{},directory(),d->PublishNotice.PublishOutcome.PUBLISHED,Clock.systemUTC());target.importAll(ACTOR,exported);target.importAll(ACTOR,exported);assertThat(target.exportAll(ACTOR)).singleElement().satisfies(r->{assertThat(r.id()).isEqualTo(item.id());assertThat(r.status()).isEqualTo("DISMISSED");assertThat(r.sourceVersion()).isEqualTo(1);});}
 private static ReviewItem.Candidate candidate(long version){return new ReviewItem.Candidate("doc:1:"+version,"documents","DOCUMENT","1",version,"PROCESSING_FAILURE","FAILED","HIGH","review.failed",Map.of("title","Bill"),"DOCUMENT","1",List.of("RETRY"));}
 private static MemberDirectory directory(){var members=List.of(new MemberSummary(LISA,"lisa","Lisa",ProductLocale.DE,true),new MemberSummary(CEDRIC,"cedric","Cedric",ProductLocale.EN,true));return new MemberDirectory(){public List<MemberSummary> listMembers(Actor actor){return members;}public Optional<MemberSummary> findMember(MemberId id){return members.stream().filter(m->m.id().equals(id)).findFirst();}};}
 private static final class MutableProducer implements ReviewProducer {List<ReviewItem.Candidate> items=List.of();public String id(){return "documents";}public List<ReviewItem.Candidate> findCurrent(Actor actor){return items;}}
 private static final class MemoryRepository implements ReviewRepository {Map<UUID,ReviewItem> all=new LinkedHashMap<>();public Optional<ReviewItem> find(UUID id){return Optional.ofNullable(all.get(id));}public Optional<ReviewItem> findByFingerprint(String f){return all.values().stream().filter(i->i.fingerprint().equals(f)).findFirst();}public List<ReviewItem> findAll(){return List.copyOf(all.values());}public void insert(ReviewItem i){all.putIfAbsent(i.id(),i);}public void update(ReviewItem i,long expected){if(i.version()!=expected+1)throw new StaleVersionException("reviewItem",i.id().toString(),expected,i.version());all.put(i.id(),i);}}
}
